*******************************************************************************************************************************	     Desk Manager*	        Patch*	 (includes NDA calls)***                For Version 2.0 of the ROM*	    June 2, 1989*** Change History**  Version 1.0 in	ROM by John Worthington***  Version 1.1 (First System Disk)*  September 1, 1986   SEG**    Contains first release of NDA stuff.**  Version 1.2 (Second System Disk)*  October 28, 1986    SEG**    The error codes had the wrong tool set number in*    desk.data.**  November 7, 1986    SEG**    SystemClick did not set the window size after a*    grow window.**    SystemClick swallowed clicks in scroll bars, the*    frame and in	the info bar.  They	are now passed*    on to DA just like Click in content.**  Version 2.1 (Third system disk, second ROM)***  Version 2.2 (Fourth system disk, second ROM)**    SaveAll zeros mmode field before calling code in*    ROM.**  Version 2.3 (Fifth system disk, second ROM)*  Changes for ROM**  The global data structures were changed so this would*  work in ROM.  No inline data storage is used.*  Individual routines are marked as changed.***  Version 2.4 (Sixth system disk (3.2), second ROM)**  SystemEvent was passing events to NDA's even when *  CDA's were active.  It now checks the NotAgain flag*  to make sure it is safe to pass them on.**  15 June 88 Harry Yee**   Prototype bit taken out of version number.***  16 Jun 88 	Steven Glass**  OpenNDA call looks for zero coming back from NDA.****  05 Aug 88	Steven Glass**  We could run into problems when going into the control*  panel during boot. The problem was that  ChooseCDA*  locks the CDATabHandle and leaves it locked.  Later*  when InstallCDA must grow the table, the SetHandleSize*  call fails.**  We fix this by setting the table size to a value large*  enough at init time so a grow is never necessary.**  [22-Feb-91 DAL:  Experiment shows that the CDA handle*  is now unlocked when you are not in the CDA menu (or*  in a CDA through the menu), so this is not a problem,*  even though the "large" value Steve chose is not very*  large.]**  23 Feb 89	Steven Glass**  Variable big is used to distinguish between small and*  large memory system patches.** 12 Mar 89	Steven Glass** Variable Big is no longer used.  All decisions are* made at run time.*** 02 Jun 89	Steven Glass** Patched out dahandler in irq_dskacc vector so that* data bank and p-reg would not be trashed.** 29 Aug 89	Harry Yee** Changed version number from $0301 to $8302.** 19-Sep-90	Dave Lyons** Rolled version to $8304.* Added GetIndDAInfo and CallDeskAcc to call table.** 25-Sep-90	Dave Lyons** Removed code that skips over the CDA menu patch on small* machines (we're not trying to support 512K machines now).** 25-Nov-90	Dave Lyons** Changed FixAppleMenu to FixAppleMenu2 in call table.** 19-Feb-91	Dave Lyons** Added GetDeskGlobal to the call table.** 11-Mar-91	Dave Lyons** Changed name of GetIndDAInfo to GetDeskAccInfo.** 17-Sep-91	Dave Lyons** Moved a lot of calls to Tool.Setup.** 21-Nov-91	Dave Lyons** NewDAHandler calls ROM directly, instead of chaining into* the $E10048 vector, because the only thing that can patch* that vector earlier than us is the ROM debugger, and chaining* in ahead of that was causing an infinite loop.** 5-Feb-92	Dave Lyons** Version $0304 for 6.0 final.**************************************************************************************************************************************************************************************************			   **	Copyright (C) 1986-1992	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	include 'all.macros'	include ':::sys.equs.asm'	include ':::desk:desk.equates.asm'****************************************************************** DACallTable** Change History** 23 Feb 89	Steven Glass** The new CDA menu is not installed if Big=0.** 12 Mar 89	Steven Glass** Removed use of BIG and added lable to ChooseCDA entry* so can be patched at run time.** (see also top of file --DAL)*****************************************************************	EXPORT DACallTableDACallTable	PROCTheBeginning	DC.L (TheEnd-TheBeginning)/4	; num calls + 1	DC.L DABootInit-1		; 0105	DC.L DAStartup-1		; 0205	DC.L DAShutdown-1		; 0305	DC.L DAVersion-1		; 0405	DC.L 0		; 0505 DAReset	DC.L DAStatus-1		; 0605 DAStatus	DC.L 0		; 0705 reserved	DC.L 0		; 0805 reserved	DC.L 0		; 0905 SaveScreen	DC.L 0		; 0A05 RestScreen	DC.L SaveAll-1		; 0B05 SaveAll	DC.L 0		; 0C05 RestAll	DC.L 0		; 0D05 (not used)	DC.L InstallNDA-1		; 0E05 InstallNDA	DC.L InstCDA-1                	; 0F05 InstallCDA	DC.L 0		; 1005 (not used)	DC.L 0  ;[ts] ChooseCDA-1	; 1105 ChooseCDA	DC.L 0		; 1205 (not used)	DC.L 0		; 1305 SetDAStrPtr	DC.L 0		; 1405 GetDAStrPtr	DC.L OpenNDA-1		; 1505	DC.L CloseNDA-1		; 1605	DC.L 0  ;[ts] SystemClick-1	; 1705	DC.L 0  ;[ts] SystemEdit-1	; 1805	DC.L 0  ;[ts] SystemTask-1	; 1905	DC.L 0  ;[ts] SystemEvent-1	; 1A05	DC.L GetNumNDAs-1		; 1B05	DC.L 0  ;[ts] CloseNDAbyWinPtr-1 	; 1C05	DC.L 0  ;[ts] CloseAllNDAs2-1	; 1D05	DC.L 0  ;[ts] FixAppleMenu2-1	; 1E05	DC.L AddToRunQ-1		; 1F05	DC.L RemoveFromRunQ-1 	; 2005	DC.L RemoveCDA-1		; 2105	DC.L 0  ;[ts] RemoveNDA-1	; 2205	dc.L 0  ;[ts] GetDeskAccInfo-1	; 2305 19-Sep-90 DAL	dc.L 0  ;[ts] CallDeskAcc-1	; 2405 19-Sep-90 DAL	dc.l 0  ;[ts] GetDeskGlobal-1	; 2505 19-Feb-91 DALTheEnd	ENDP*****************************************************************DABootInit	PROC** Description*** Inputs:*	none** Outputs:*	none** External Refs:***	import BigMachine	;removed 25-Sep-90 DAL** Entry Points:*	none*	longa on	; mode	longi on** Change History** 3 Jun 87     JW and SEG** When SaveAll and RestoreAll deal with	mmode, it is possible* for the code to become confused.  The	code that looks for* the mouse card initializes the mmode word in 8 bit mode.* It later reads the word in 16 bit mode and if the* uninitialized byte powered up with the high bit set,* then the code thinks the mouse is off	even when it is on.** The fix here is to always zero the mmode each time SaveAll* is called.  To do	this we patch the addess of in the* call table.** 2 Oct 87	    Steven Glass** The error code sent to death mgr had wrong high byte (6* instead of 5).** 24 Oct 88	Steven Glass** No longer care about orignal value of SAVEALL.  Original code* was written to read address of SaveAll out of table.  But* since this does not have to run with the original rom anymore* I cna jump into a fixed location.** 23 Feb 89	Steven Glass** When Big is not set to 1, we do not change KeyInput.*** 12 Mar 89	Steven Glass** Remove compiler switch for big and decide at run time.* If machine is big we change KeyInput and install the* address of the new choosecda routine into the call table** 02 Jun 89	Steven Glass** Patched out the old irq_dskacc vector out.  The code in ROM* did a push p followed by a pull b.  This patch saves b and p* before calling the ROM and restores them after.** [See top of file for other notes]********************************************************************	lda >BigMachine	;removed 25-Sep-90 DAL***	beq @NoCDAPatch;;; Tool.Setup now inits KeyInput;;;	lda #MonKeyIn;;;	sta >KeyInput*** Removed 27-Nov-90 DAL (we can put it directly in the patch table now)*	lda #ChooseCDA-1*	sta >ChooseCDAAddr*	lda #^ChooseCDA-1*	sta >ChooseCDAAddr+2*** @NoCDAPatch	php	;27-Nov-90 DAL (I'm paranoid)	sei	;27-Nov-90 DAL;;; Removed 21-Nov-91 DAL for compatibility with ROM debugger;	lda >IRQ_DSKACC	; save the old irq vector;	sta >OldDAHandler;	lda >IRQ_DSKACC+2;	sta >OldDAHandler+2	lda #NewDAHandler	; install our new one	sta >IRQ_DSKACC+1	lda #>NewDAHandler	sta >IRQ_DSKACC+2	plp	;27-Nov-90 DAL	jsr DoNDAInit	sep #$30	longa off	longi off	lda #$00	sta >IsPanelActive	rep #$30	longa on	longi on	jml oEndCall0;; The old handler can trash dbr and p-reg so we save them dbr before the call; and restore them after.;NewDAHandler	phb	php;;;	jsl OldDAHandler	jsl $FEADB9	;21-Nov-91 DAL	plp	plb	clc	rtl;;;OldDAHandler	dc.L 0	ENDP*****************************************************************DAVersion	PROC** Returns the version number of the desk manager*** Inputs:*	none** Outputs:*	work : The patched version number** External Refs:*	Falls into the boot init code.** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #$0304	;5-Feb-92 DAL	sta 7,s	lda #0	clc	RTL	ENDP***************************************************************** SaveAll** Change History** 3 Jun 87     JW and SEG** When SaveAll and RestoreAll deal with	mmode, it is possible* for the code to become confused.  The	code that looks for* the mouse card initializes the mmode word in 8 bit mode.* It later reads the word in 16 bit mode and if the* uninitialized byte powered up with the high bit set,* then the code thinks the mouse is off	even when it is on.** The fix here is to always zero the mmode before calling* the old code.** 24 Oct 88	Steven Glass** This only has to work with one rom now so I can jump into* the right location instead of finding it dynaically.****************************************************************	EXPORT SaveAllSaveAll	PROC	lda #0	sta >mmode	jml $FEAFCB	ENDP	END